static String classify(Throwable t) {
    for (Throwable c = t; c != null; c = c.getCause()) {
        if (c instanceof java.net.UnknownHostException) return "DNS";
        if (c instanceof java.net.NoRouteToHostException) return "L3";
        if (c instanceof java.net.ConnectException) return "L4";
        if (c instanceof java.net.SocketTimeoutException) return "L3/L4";
        if (c instanceof javax.net.ssl.SSLException) return "L6";
    }
    return "I/O";
}
